SELECT r.workspace_id, r.channel_id, r.root_thread_ts, r.latest_job_id, r.source_job_id, r.initiator_user_id, r.desired_status, r.agent_status, r.session_status, r.revision, r.sent_revision, r.claimed_revision, r.state, r.attempts, r.next_attempt_at, r.refresh_at, r.rate_limited_until, r.first_sent_at, r.last_sent_at, r.reason, r.warning, r.updated_at FROM agent_session_publications r WHERE $criteria.CompositeIn("r", $WriterKeys)